module LIFO_Stack #(parameter DEPTH = 8, parameter WIDTH = 8) (  
    input wire clk,  
    input wire rst,  
    input wire push,  
    input wire pop,  
    input wire [WIDTH-1:0] data_in,  
    output reg [WIDTH-1:0] data_out,  
    output reg empty,  
    output reg full  
);  
    reg [WIDTH-1:0] stack [0:DEPTH-1];  
    reg [3:0] top;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            top <= 0;  
            empty <= 1;  
            full <= 0;  
            data_out <= 0;  
        end else begin  
            if (push && !full) begin  
                stack[top] <= data_in;  
                top <= top + 1;  
                empty <= 0;  
                if (top + 1 == DEPTH)  
                    full <= 1;  
            end  
            if (pop && !empty) begin  
                top <= top - 1;  
                data_out <= stack[top - 1];  
                if (top - 1 == 0)  
                    empty <= 1;  
                full <= 0;  
            end  
        end  
    end  
endmodule

