`timescale 1ns/1ps

module divider_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [7:0] dividend;
    reg [7:0] divisor;
    reg rst;
    wire done;
    wire [7:0] quotient;
    wire [7:0] remainder;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    divider dut (
        .clk(clk),
        .dividend(dividend),
        .divisor(divisor),
        .rst(rst),
        .done(done),
        .quotient(quotient),
        .remainder(remainder)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            dividend = 0;
            divisor = 0;
            repeat(2) @(posedge clk);
            #1 rst = 0;

            @(posedge clk);
        end
        endtask
    task wait_and_check;

        input [7:0] exp_q;
        input [7:0] exp_r;
        begin


            fork: timeout_block
                begin
                    wait(done == 1);
                end
                begin
                    repeat(100) @(posedge clk);
                end
            join_any
            disable timeout_block;

            if (done !== 1) begin
                $display("FAIL: Timeout waiting for done signal");
                fail_count = fail_count + 1;
            end else begin
                #1;

                check_outputs(1'b1, exp_q, exp_r);
            end
        end
        endtask

    task testcase001;

        begin
            test_num = 1;
            $display("Test Case %0d: 20 / 5", test_num);
            reset_dut();
            dividend = 8'd20;
            divisor = 8'd5;
            wait_and_check(8'd4, 8'd0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Test Case %0d: 20 / 3", test_num);
            reset_dut();
            dividend = 8'd20;
            divisor = 8'd3;
            wait_and_check(8'd6, 8'd2);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Test Case %0d: 0 / 10", test_num);
            reset_dut();
            dividend = 8'd0;
            divisor = 8'd10;
            wait_and_check(8'd0, 8'd0);
        end
        endtask

    task testcase004;

        begin
            test_num = 4;
            $display("Test Case %0d: 5 / 10", test_num);
            reset_dut();
            dividend = 8'd5;
            divisor = 8'd10;
            wait_and_check(8'd0, 8'd5);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("Test Case %0d: 255 / 1", test_num);
            reset_dut();
            dividend = 8'd255;
            divisor = 8'd1;
            wait_and_check(8'd255, 8'd0);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            $display("Test Case %0d: 128 / 128", test_num);
            reset_dut();
            dividend = 8'd128;
            divisor = 8'd128;
            wait_and_check(8'd1, 8'd0);
        end
        endtask

    task testcase007;

        begin
            test_num = 7;
            $display("Test Case %0d: 255 / 2", test_num);
            reset_dut();
            dividend = 8'd255;
            divisor = 8'd2;
            wait_and_check(8'd127, 8'd1);
        end
        endtask

    task testcase008;

        begin
            test_num = 8;
            $display("Test Case %0d: 100 / 7", test_num);
            reset_dut();
            dividend = 8'd100;
            divisor = 8'd7;
            wait_and_check(8'd14, 8'd2);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("divider Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_done;
        input [7:0] expected_quotient;
        input [7:0] expected_remainder;
        begin
            if (expected_done === (expected_done ^ done ^ expected_done) &&
                expected_quotient === (expected_quotient ^ quotient ^ expected_quotient) &&
                expected_remainder === (expected_remainder ^ remainder ^ expected_remainder)) begin
                $display("PASS");
                $display("  Outputs: done=%b, quotient=%h, remainder=%h",
                         done, quotient, remainder);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: done=%b, quotient=%h, remainder=%h",
                         expected_done, expected_quotient, expected_remainder);
                $display("  Got:      done=%b, quotient=%h, remainder=%h",
                         done, quotient, remainder);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, dividend, divisor, rst, done, quotient, remainder);
    end

endmodule

